{$ param title label="Title" default="Ready to get started?" description="Main CTA heading." $}
{$ param primary_label label="Primary Label" default="Get Started" description="Primary button text." $}
{$ param primary_href label="Primary URL" default="#" description="Primary button URL." $}
{$ param secondary_label label="Secondary Label" default="" description="Optional secondary button text." $}
{$ param secondary_href label="Secondary URL" default="#" description="Optional secondary button URL." $}
{$ param bg_class label="Background Classes" default="" description="Tailwind background and text color classes (optional)." $}

<div class="ss-cta ss-org-account {$= bg_class $} p-8 mb-8 text-center">
  <div class="ss-org-account__content max-w-[960px] mx-auto">
    <h2>{$= title $}</h2>
    {$ slot body $}
      <p>Explain why someone should click.</p>
    {$ /slot $}
    <div class="ss-org-account__btns">
      <a href="{$= primary_href $}" class="btn btn-primary">{$= primary_label $}</a>
      {$ if secondary_label $}<a href="{$= secondary_href $}" class="btn btn-primary">{$= secondary_label $}</a>{$ /if $}
    </div>
  </div>
</div>
